const raw = $('Extract Story Log').first().json;
const log = raw.data ?? raw;
const used = log.used || [];
if (!used.length) throw new Error('No stories. Run Module 4 first.');
const id = used[used.length - 1].id;
return [{ json: { story_id: id, scenes_path: `/data/output/scenes/${id}.json`, audio_manifest_path: `/data/output/audio/${id}_audio.json` } }];

const scRaw = $('Extract Scenes').first().json;
const sc = scRaw.data ?? scRaw;
const system = $('Extract Flow System').first().json.data;

const charLines = sc.characters.map(c => `- ${c.name}: ${c.visual_description}`).join('\n');
const sceneLines = sc.scenes.map(s => `SCENE ${s.scene_number}\n  Setting: ${s.setting}\n  Characters present: ${(s.characters_present||[]).join(', ') || 'none'}\n  Action: ${s.action}`).join('\n\n');

const userPrompt = `Story: ${sc.title}\n\nCHARACTERS (exact fixed appearance - repeat the full look every time the character appears):\n${charLines}\n\nWrite one self-contained Veo visual prompt per scene below. Return a JSON array 'shots' with one object per scene in order.\n\n${sceneLines}`;

const responseSchema = {
  type: 'OBJECT',
  properties: {
    shots: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          scene_number: { type: 'INTEGER' },
          veo_prompt: { type: 'STRING' },
          camera_move: { type: 'STRING' }
        },
        required: ['scene_number', 'veo_prompt', 'camera_move']
      }
    }
  },
  required: ['shots']
};

const body = {
  systemInstruction: { parts: [{ text: system }] },
  contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
  generationConfig: { responseMimeType: 'application/json', responseSchema, temperature: 0.8, maxOutputTokens: 32768 }
};
return [{ json: { model: 'gemini-2.5-flash', story_id: sc.story_id, body } }];

const resp = $input.first().json;
const scRaw = $('Extract Scenes').first().json;
const sc = scRaw.data ?? scRaw;
let am = {};

const text = (resp.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
if (!text) throw new Error('Gemini returned no text.');
const parsed = JSON.parse(text);
const shots = parsed.shots || [];
const byScene = {}; shots.forEach(s => byScene[s.scene_number] = s);
const durByScene = {}; (am.clips||[]).forEach(c => durByScene[c.scene_number] = c.duration_seconds);

function scrub(s){
  return String(s||'')
    .replace(/extreme close-?ups?/gi,'very close view')
    .replace(/close-?ups?/gi,'close view')
    .replace(/wide(?:-| )angle shots?/gi,'broad view')
    .replace(/wide shots?/gi,'broad view')
    .replace(/establishing shots?/gi,'broad view')
    .replace(/aerial shots?/gi,'high view from above')
    .replace(/(?:dolly|crane|tracking) shots?/gi,'smooth moving view')
    .replace(/\bpanning\b/gi,'gliding')
    .replace(/\bpan\b/gi,'glide')
    .replace(/\btilting\b/gi,'shifting')
    .replace(/\bzoom(?:ing)?(?: in| out)?\b/gi,'move closer')
    .replace(/\bthe camera\b/gi,'the view')
    .replace(/\bcamera\b/gi,'view')
    .replace(/\bshots?\b/gi,'view')
    .replace(/\b([Aa])n (?=very |broad |close |smooth |high )/g,'$1 ').replace(/\s{2,}/g,' ').trim();
}
function fullPrompt(visual, narration) {
  const v = scrub((visual || '').trim());
  const n = (narration || '').replace(/\s+/g, ' ').trim();
  return `${v}\n\nAUDIO: A warm, gentle female storyteller narrates softly and clearly: \"${n}\" Add soft, gentle background ambience and light, whimsical music. No other voices.`;
}

let md = `# Flow Shot Sheet - ${sc.title}\n\n`;
md += `Story ID: ${sc.story_id}\n\n`;
md += `HOW TO USE THIS IN FLOW:\n`;
md += `1. Open Flow (labs.google/flow) and start a new project (text-to-video).\n`;
md += `2. For each scene: paste the whole prompt block (it includes the visuals AND the narration line as audio). Generate.\n`;
md += `3. Use Flow's \"Extend\" to grow each clip to roughly its Target length.\n`;
md += `4. Arrange all scenes in order on the timeline and export ONE 1920x1080 video (with audio).\n`;
md += `5. Save the export as: output\\\\flow_in\\\\${sc.story_id}.mp4  (then run the publish workflow).\n\n`;
md += `Tip: keep each character's full description identical every time they appear (the prompts already do this) so Flow keeps them looking the same.\n\n---\n\n`;

let totalTarget = 0;
for (const scene of sc.scenes) {
  const n = scene.scene_number;
  const shot = byScene[n] || {};
  const dur = durByScene[n] || scene.duration_seconds || 8;
  totalTarget += dur;
  md += `## Scene ${n}  (Target: ~${Math.round(dur)}s)\n\n`;
  md += `Camera: ${shot.camera_move || 'slow push-in'}\n\n`;
  md += `PROMPT (paste the whole block into Flow):\n`;
  md += '```\n' + fullPrompt(shot.veo_prompt || scene.action, scene.narration) + '\n```\n\n---\n\n';
}
md += `Total target length: ~${Math.round(totalTarget)}s (~${(totalTarget/60).toFixed(1)} min).\n`;

const jsonSheet = { story_id: sc.story_id, title: sc.title, total_target_seconds: Math.round(totalTarget*10)/10, shots: sc.scenes.map(scene => ({ scene_number: scene.scene_number, target_seconds: durByScene[scene.scene_number] || scene.duration_seconds, camera_move: (byScene[scene.scene_number]||{}).camera_move || '', prompt: fullPrompt((byScene[scene.scene_number]||{}).veo_prompt || scene.action, scene.narration) })) };

return [{ json: {
  mdB64: Buffer.from(md, 'utf8').toString('base64'),
  jsonSheet,
  md_path: `/data/output/flow/${sc.story_id}_flow-sheet.md`,
  json_path: `/data/output/flow/${sc.story_id}_flow-sheet.json`,
  story_id: sc.story_id,
  shot_count: shots.length,
  total_target_seconds: Math.round(totalTarget*10)/10
} }];
